import '@servicenow/sdk/global'
import { BooleanColumn, StringColumn, IntegerColumn } from '@servicenow/sdk/core'
import { Flow, trigger, wfa } from '@servicenow/sdk/automation'
import { ActionDefinition } from '@servicenow/sdk/automation'

// Action definition for testing datapills in flow logic
export const testActionDef = ActionDefinition({
    $id: Now.ID['flow-logic-action-def'],
    name: 'Flow Logic Action Sample',
    annotation: 'Action for flow logic datapill testing',
    description: 'Test action definition for flow logic',
    inputs: {
        incidentId: StringColumn({
            label: 'Incident ID',
            mandatory: true,
        }),
        workNotes: StringColumn({
            label: 'Work Notes',
            mandatory: false,
        }),
        priority: IntegerColumn({
            label: 'Priority',
            mandatory: false,
        }),
    },
    outputs: {
        status: StringColumn({
            label: 'Status',
            mandatory: true,
        }),
        requestId: StringColumn({
            label: 'Request ID',
            mandatory: true,
        }),
        isSuccess: BooleanColumn({
            label: 'Is Success',
            mandatory: true,
        }),
    },
})

// =============================================================================
// Test Flow: Datapills in If/ElseIf/Else Flow Logic
// =============================================================================
export const flowLogicIfElseDatapills = Flow(
    {
        $id: Now.ID['flow-logic-if-else-datapills'],
        name: 'Flow Logic If-Else Datapills Test',
        description: 'Test datapills in If, ElseIf, and Else flow logic',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
        flowVariables: {
            threshold: IntegerColumn({
                label: 'Threshold',
                mandatory: true,
            }),
            statusFilter: StringColumn({
                label: 'Status Filter',
                mandatory: true,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['flow-logic-if-else-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // Action to get a result for datapill testing
        const actionResult = wfa.action(
            testActionDef,
            {
                $id: Now.ID['flow-logic-action-1'],
                uuid: 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee',
            },
            {
                incidentId: wfa.dataPill(params.trigger.current.sys_id, 'string'),
                workNotes: 'Initial action',
                priority: 1,
            }
        )

        // If with trigger datapill in condition
        wfa.flowLogic.if(
            {
                $id: Now.ID['flow-logic-if-trigger-pill'],
                condition: `${wfa.dataPill(params.trigger.current.priority, 'integer')}==1`,
                annotation: 'Check if priority is Critical',
            },
            () => {
                wfa.action(
                    testActionDef,
                    { $id: Now.ID['flow-logic-if-action-1'], uuid: 'if111111-1111-1111-1111-111111111111' },
                    {
                        incidentId: wfa.dataPill(params.trigger.current.sys_id, 'string'),
                        workNotes: 'Priority is Critical',
                    }
                )
            }
        )

        // ElseIf with action output datapill in condition
        wfa.flowLogic.elseIf(
            {
                $id: Now.ID['flow-logic-elseif-action-pill'],
                condition: `${wfa.dataPill(actionResult.status, 'string')}=='In Progress'`,
                annotation: 'Check if status is In Progress',
            },
            () => {
                wfa.action(
                    testActionDef,
                    { $id: Now.ID['flow-logic-elseif-action-1'], uuid: 'elseif11-1111-1111-1111-111111111111' },
                    {
                        incidentId: wfa.dataPill(actionResult.requestId, 'string'),
                        workNotes: 'Status is In Progress',
                    }
                )
            }
        )

        // ElseIf with flow variable datapill in condition
        wfa.flowLogic.elseIf(
            {
                $id: Now.ID['flow-logic-elseif-flowvar-pill'],
                condition: `${wfa.dataPill(params.flowVariables.statusFilter, 'string')}=='Pending'`,
                annotation: 'Check if flow variable status is Pending',
            },
            () => {
                wfa.action(
                    testActionDef,
                    { $id: Now.ID['flow-logic-elseif-action-2'], uuid: 'elseif22-2222-2222-2222-222222222222' },
                    {
                        incidentId: wfa.dataPill(params.trigger.current.sys_id, 'string'),
                        workNotes: `Status filter is ${wfa.dataPill(params.flowVariables.statusFilter, 'string')}`,
                    }
                )
            }
        )

        // ElseIf with template expression containing multiple datapills
        wfa.flowLogic.elseIf(
            {
                $id: Now.ID['flow-logic-elseif-template-pill'],
                condition: `${wfa.dataPill(params.trigger.current.priority, 'integer')}==${wfa.dataPill(params.flowVariables.threshold, 'integer')}`,
                annotation: 'Check if priority equals threshold',
            },
            () => {
                wfa.action(
                    testActionDef,
                    { $id: Now.ID['flow-logic-elseif-action-3'], uuid: 'elseif33-3333-3333-3333-333333333333' },
                    {
                        incidentId: wfa.dataPill(params.trigger.current.sys_id, 'string'),
                        workNotes: 'Priority equals threshold',
                    }
                )
            }
        )

        // Else block
        wfa.flowLogic.else(
            {
                $id: Now.ID['flow-logic-else-default'],
                annotation: 'Default case',
            },
            () => {
                wfa.action(
                    testActionDef,
                    { $id: Now.ID['flow-logic-else-action-1'], uuid: 'else1111-1111-1111-1111-111111111111' },
                    {
                        incidentId: wfa.dataPill(params.trigger.current.sys_id, 'string'),
                        workNotes: 'Default action executed',
                    }
                )
            }
        )
    }
)

// =============================================================================
// Test Flow: Nested Flow Logic with Datapills
// =============================================================================
export const flowLogicNestedDatapills = Flow(
    {
        $id: Now.ID['flow-logic-nested-datapills'],
        name: 'Flow Logic Nested Datapills Test',
        description: 'Test datapills in nested flow logic structures',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
        flowVariables: {
            level: StringColumn({
                label: 'Level',
                mandatory: true,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['flow-logic-nested-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        const initialAction = wfa.action(
            testActionDef,
            {
                $id: Now.ID['flow-logic-nested-initial-action'],
                uuid: 'nested00-0000-0000-0000-000000000000',
            },
            {
                incidentId: wfa.dataPill(params.trigger.current.sys_id, 'string'),
                workNotes: 'Initial action',
            }
        )

        // Outer If with datapill condition
        wfa.flowLogic.if(
            {
                $id: Now.ID['flow-logic-nested-outer-if'],
                condition: `${wfa.dataPill(initialAction.status, 'string')}=='Active'`,
                annotation: 'Outer if - check status Active',
            },
            () => {
                wfa.action(
                    testActionDef,
                    { $id: Now.ID['flow-logic-nested-outer-if-action'], uuid: 'nested11-1111-1111-1111-111111111111' },
                    {
                        incidentId: wfa.dataPill(params.trigger.current.sys_id, 'string'),
                        workNotes: 'Inside outer if',
                    }
                )

                // Nested If inside outer If with trigger datapill
                wfa.flowLogic.if(
                    {
                        $id: Now.ID['flow-logic-nested-inner-if'],
                        condition: `${wfa.dataPill(params.trigger.current.priority, 'integer')}==1`,
                        annotation: 'Inner if - check priority Critical',
                    },
                    () => {
                        wfa.action(
                            testActionDef,
                            {
                                $id: Now.ID['flow-logic-nested-inner-if-action'],
                                uuid: 'nested22-2222-2222-2222-222222222222',
                            },
                            {
                                incidentId: wfa.dataPill(params.trigger.current.sys_id, 'string'),
                                workNotes: 'Inside nested if - Critical',
                            }
                        )
                    }
                )

                // Nested ElseIf with flow variable datapill
                wfa.flowLogic.elseIf(
                    {
                        $id: Now.ID['flow-logic-nested-inner-elseif'],
                        condition: `${wfa.dataPill(params.flowVariables.level, 'string')}=='High'`,
                        annotation: 'Inner elseIf - check level High',
                    },
                    () => {
                        wfa.action(
                            testActionDef,
                            {
                                $id: Now.ID['flow-logic-nested-inner-elseif-action'],
                                uuid: 'nested33-3333-3333-3333-333333333333',
                            },
                            {
                                incidentId: wfa.dataPill(params.trigger.current.sys_id, 'string'),
                                workNotes: 'Inside nested elseIf - High level',
                            }
                        )
                    }
                )

                // Nested Else
                wfa.flowLogic.else(
                    {
                        $id: Now.ID['flow-logic-nested-inner-else'],
                        annotation: 'Inner else - default priority',
                    },
                    () => {
                        wfa.action(
                            testActionDef,
                            {
                                $id: Now.ID['flow-logic-nested-inner-else-action'],
                                uuid: 'nested44-4444-4444-4444-444444444444',
                            },
                            {
                                incidentId: wfa.dataPill(params.trigger.current.sys_id, 'string'),
                                workNotes: 'Inside nested else - default',
                            }
                        )
                    }
                )
            }
        )

        // Outer Else
        wfa.flowLogic.else(
            {
                $id: Now.ID['flow-logic-nested-outer-else'],
                annotation: 'Outer else - status not Active',
            },
            () => {
                wfa.action(
                    testActionDef,
                    {
                        $id: Now.ID['flow-logic-nested-outer-else-action'],
                        uuid: 'nested55-5555-5555-5555-555555555555',
                    },
                    {
                        incidentId: wfa.dataPill(params.trigger.current.sys_id, 'string'),
                        workNotes: 'Inside outer else',
                    }
                )
            }
        )
    }
)
